-- Generated by python3 scripts/build-supabase-setup.py. Do not edit directly.
-- Paste this ENTIRE file into the Supabase SQL Editor and run as postgres.
-- Fresh installation or upgrade: preserves existing accounts, ratings and records.
-- One transaction: any error rolls back the complete setup. Safe to run again.
begin;
set local lock_timeout = '10s';
set local statement_timeout = '120s';

-- Source: Supabase/schema.sql
-- Base schema. For a complete installation, run the generated setup.sql instead.
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  nickname text not null check (char_length(nickname) between 2 and 12),
  rating integer not null default 1000 check (rating >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.matches (
  id uuid primary key default gen_random_uuid(),
  room_id text not null unique,
  winner_id uuid references public.profiles(id),
  result jsonb not null,
  played_at timestamptz not null default now()
);

alter table public.profiles enable row level security;
alter table public.matches enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='profile read') then
    create policy "profile read" on public.profiles for select using (true);
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='profile self update') then
    create policy "profile self update" on public.profiles for update using (auth.uid() = id) with check (auth.uid() = id);
  end if;
  -- Reapplying this base file must not reopen history made private by the member migration.
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='matches' and policyname in ('match read','member match history')) then
    create policy "match read" on public.matches for select using (true);
  end if;
end;
$$;

-- match insert/update는 service_role을 가진 권위 서버만 수행한다. 클라이언트 정책은 만들지 않는다.

-- Source: Supabase/migrations/20261102_team_match_history.sql
-- Apply once in the Supabase SQL Editor before deploying the updated game server.
-- Keep old match rows intact; room IDs identify lobbies, not unique matches.
alter table public.matches drop constraint if exists matches_room_id_key;
alter table public.matches add column if not exists mode text not null default 'duel';
create table if not exists public.match_participants (
  match_id uuid not null references public.matches(id) on delete cascade,
  user_id uuid not null references public.profiles(id),
  team text check (team is null or team in ('blue', 'pink')),
  outcome text not null check (outcome in ('win', 'loss', 'draw')),
  primary key (match_id, user_id)
);
alter table public.match_participants enable row level security;
drop policy if exists "match participant read" on public.match_participants;
create policy "match participant read" on public.match_participants for select using (true);

-- One RPC call records the match and all players in one database transaction.
-- Reusing a match ID is safe if a caller retries after a lost response.
create or replace function public.record_match(
  p_match_id uuid, p_room_id text, p_mode text, p_winner_id uuid,
  p_result jsonb, p_participants jsonb
) returns void language plpgsql security invoker set search_path = public as $$
begin
  insert into public.matches (id, room_id, mode, winner_id, result)
    values (p_match_id, p_room_id, p_mode, p_winner_id, p_result)
    on conflict (id) do nothing;
  insert into public.match_participants (match_id, user_id, team, outcome)
    select p_match_id, (p->>'user_id')::uuid, p->>'team', p->>'outcome'
    from jsonb_array_elements(p_participants) as p
    on conflict (match_id, user_id) do nothing;
end;
$$;
revoke all on function public.record_match(uuid, text, text, uuid, jsonb, jsonb) from public, anon, authenticated;
grant execute on function public.record_match(uuid, text, text, uuid, jsonb, jsonb) to service_role;

-- Source: Supabase/migrations/20261102_rankings.sql
-- Apply after 20261102_team_match_history.sql, before deploying score/rank server code.
-- Existing matches, profile ratings and participant history are preserved.
-- Only initialize newly introduced counters. Existing totals may include imported
-- or archived matches and must not be replaced by the remaining history on rerun.
do $$
declare
  new_wins boolean; new_losses boolean; new_draws boolean; new_score boolean;
begin
  select not exists(select 1 from pg_attribute where attrelid='public.profiles'::regclass and attname='wins' and not attisdropped),
         not exists(select 1 from pg_attribute where attrelid='public.profiles'::regclass and attname='losses' and not attisdropped),
         not exists(select 1 from pg_attribute where attrelid='public.profiles'::regclass and attname='draws' and not attisdropped),
         not exists(select 1 from pg_attribute where attrelid='public.profiles'::regclass and attname='score' and not attisdropped)
    into new_wins,new_losses,new_draws,new_score;
  alter table public.profiles
    add column if not exists wins integer not null default 0 check (wins >= 0),
    add column if not exists losses integer not null default 0 check (losses >= 0),
    add column if not exists draws integer not null default 0 check (draws >= 0),
    add column if not exists score bigint not null default 0 check (score >= 0);
  alter table public.match_participants
    add column if not exists score integer not null default 0 check (score between 0 and 1000000);
  if new_wins or new_losses or new_draws or new_score then
    update public.profiles p set
      wins = case when new_wins then s.wins else p.wins end,
      losses = case when new_losses then s.losses else p.losses end,
      draws = case when new_draws then s.draws else p.draws end,
      score = case when new_score then s.score else p.score end
    from (
      select user_id,
        count(*) filter (where outcome = 'win') as wins,
        count(*) filter (where outcome = 'loss') as losses,
        count(*) filter (where outcome = 'draw') as draws,
        sum(score) as score
      from public.match_participants group by user_id
    ) s where p.id = s.user_id;
  end if;
end;
$$;

-- RLS protects which profile can be edited; column privileges protect its rankings.
-- An authenticated client may change only its nickname, never rating or statistics.
revoke update on public.profiles from anon, authenticated;
revoke update (id, nickname, rating, created_at, updated_at, wins, losses, draws, score)
  on public.profiles from anon, authenticated;
grant update (nickname) on public.profiles to authenticated;

create or replace function public.record_match(
  p_match_id uuid, p_room_id text, p_mode text, p_winner_id uuid,
  p_result jsonb, p_participants jsonb
) returns void language plpgsql security invoker set search_path = public as $$
declare inserted_id uuid;
begin
  if p_mode not in ('team', 'duel') then raise exception 'Invalid match mode'; end if;
  if p_participants is null or jsonb_typeof(p_participants) <> 'array' or jsonb_array_length(p_participants) > 8 then
    raise exception 'Invalid participants';
  end if;
  insert into public.matches (id, room_id, mode, winner_id, result)
    values (p_match_id, p_room_id, p_mode, p_winner_id, p_result)
    on conflict (id) do nothing returning id into inserted_id;
  -- Duplicate/retried records cannot increment score or rating twice.
  if inserted_id is null then return; end if;

  with recorded as (
    insert into public.match_participants (match_id, user_id, team, outcome, score)
      select p_match_id, (p->>'user_id')::uuid, p->>'team', p->>'outcome', coalesce((p->>'score')::integer, 0)
      from jsonb_array_elements(p_participants) as p
      returning user_id, outcome, score
  )
  update public.profiles profile set
    rating = greatest(0, profile.rating + case recorded.outcome when 'win' then 25 when 'loss' then -15 else 5 end),
    wins = profile.wins + case when recorded.outcome = 'win' then 1 else 0 end,
    losses = profile.losses + case when recorded.outcome = 'loss' then 1 else 0 end,
    draws = profile.draws + case when recorded.outcome = 'draw' then 1 else 0 end,
    score = profile.score + recorded.score,
    updated_at = now()
  from recorded where profile.id = recorded.user_id;
end;
$$;
revoke all on function public.record_match(uuid, text, text, uuid, jsonb, jsonb) from public, anon, authenticated;
grant execute on function public.record_match(uuid, text, text, uuid, jsonb, jsonb) to service_role;
create index if not exists profiles_leaderboard_idx on public.profiles (rating desc, score desc, nickname);

-- Source: Supabase/migrations/20261106_team_elo.sql
-- Apply after 20261102_rankings.sql. Existing ratings, statistics and history are unchanged.
-- Elo uses the latest persisted ratings immediately before this result is applied;
-- delayed result delivery can therefore affect the ordering of later updates.
create or replace function public.record_match(
  p_match_id uuid, p_room_id text, p_mode text, p_winner_id uuid,
  p_result jsonb, p_participants jsonb
) returns void language plpgsql security invoker set search_path = public as $$
declare
  inserted_id uuid; first_duelist uuid;
  participant_count integer; locked_count integer;
  outcome_a text; outcome_b text; outcomes_a integer; outcomes_b integer;
  mean_a numeric; mean_b numeric; expected_a numeric; actual_a numeric;
  delta_a integer := 0;
begin
  if p_mode is null or p_mode not in ('team','duel') then raise exception 'Invalid match mode'; end if;
  if p_participants is null or jsonb_typeof(p_participants) <> 'array' or jsonb_array_length(p_participants) > 8 then
    raise exception 'Invalid participants';
  end if;
  -- Preserve the existing retry contract, including a historical subset payload.
  if exists(select 1 from public.matches where id=p_match_id) then return; end if;
  participant_count := jsonb_array_length(p_participants);
  if p_mode='duel' and participant_count>2 then raise exception 'Invalid duel participants'; end if;
  if exists(select 1 from jsonb_array_elements(p_participants) item where jsonb_typeof(item)<>'object') then
    raise exception 'Invalid participants';
  end if;
  if exists(select 1 from jsonb_to_recordset(p_participants) as p(user_id uuid, team text, outcome text, score integer)
    where user_id is null or outcome is null or outcome not in ('win','loss','draw')
      or coalesce(score,0) not between 0 and 1000000
      or (p_mode='team' and (team is null or team not in ('blue','pink')))
      or (p_mode='duel' and team is not null))
    or participant_count<>(select count(distinct user_id) from jsonb_to_recordset(p_participants) as p(user_id uuid))
  then raise exception 'Invalid participants or outcomes' using errcode='23514'; end if;
  if p_winner_id is not null and not exists(
    select 1 from jsonb_to_recordset(p_participants) as p(user_id uuid) where user_id=p_winner_id)
  then raise exception 'Winner must be a participant' using errcode='23514'; end if;

  if p_mode='duel' then
    select user_id into first_duelist from jsonb_to_recordset(p_participants) as p(user_id uuid) order by user_id limit 1;
  end if;
  select min(outcome) filter(where side_a), min(outcome) filter(where not side_a),
         count(distinct outcome) filter(where side_a), count(distinct outcome) filter(where not side_a)
    into outcome_a,outcome_b,outcomes_a,outcomes_b
    from (select outcome,case when p_mode='team' then team='blue' else user_id=first_duelist end as side_a
      from jsonb_to_recordset(p_participants) as p(user_id uuid,team text,outcome text)) sides;
  if outcomes_a>1 or outcomes_b>1 or (outcome_a is not null and outcome_b is not null and not (
    (outcome_a='win' and outcome_b='loss') or (outcome_a='loss' and outcome_b='win') or (outcome_a='draw' and outcome_b='draw')))
  then raise exception 'Inconsistent opposing outcomes' using errcode='23514'; end if;

  -- Lock the entire roster in UUID order BEFORE matches.winner_id or participant
  -- foreign-key inserts acquire key-share locks. This avoids lock-upgrade cycles
  -- between overlapping matches and serializes their pre-application snapshots.
  perform profile.id from public.profiles profile
    join jsonb_to_recordset(p_participants) as p(user_id uuid) on p.user_id=profile.id
    order by profile.id for update of profile;
  get diagnostics locked_count = row_count;
  if locked_count<>participant_count then raise exception 'Missing participant profile' using errcode='23503'; end if;

  insert into public.matches(id,room_id,mode,winner_id,result)
    values(p_match_id,p_room_id,p_mode,p_winner_id,p_result)
    on conflict(id) do nothing returning id into inserted_id;
  -- Another transaction may have committed this identity while we waited for rows.
  if inserted_id is null then return; end if;

  select avg(rating) filter(where side_a), avg(rating) filter(where not side_a)
    into mean_a,mean_b
    from (select profile.rating::numeric rating,
      case when p_mode='team' then p.team='blue' else p.user_id=first_duelist end as side_a
      from public.profiles profile join jsonb_to_recordset(p_participants) as p(user_id uuid,team text)
        on p.user_id=profile.id) sides;
  -- Partial legacy histories still count statistics but cannot invent an opponent.
  if mean_a is not null and mean_b is not null then
    expected_a := 1 / (1 + power(10::numeric,least(800::numeric,greatest(-800::numeric,mean_b-mean_a))/400));
    actual_a := case outcome_a when 'win' then 1 when 'draw' then 0.5 else 0 end;
    -- PostgreSQL numeric round ties away from zero, matching signed JS magnitude rounding.
    -- Derive the other side by exact negation, never by a second rounding calculation.
    delta_a := round(32 * (actual_a-expected_a))::integer;
  end if;
  with recorded as (
    insert into public.match_participants(match_id,user_id,team,outcome,score)
      select p_match_id,user_id,team,outcome,coalesce(score,0)
      from jsonb_to_recordset(p_participants) as p(user_id uuid,team text,outcome text,score integer)
      returning user_id,team,outcome,score
  )
  update public.profiles profile set
    -- Bounds can break zero-sum at the edges; bigint prevents int32 addition overflow.
    rating = least(2147483647::bigint,greatest(0::bigint,profile.rating::bigint +
      case when (p_mode='team' and recorded.team='blue') or (p_mode='duel' and recorded.user_id=first_duelist)
        then delta_a else -delta_a end))::integer,
    wins=profile.wins+case when recorded.outcome='win' then 1 else 0 end,
    losses=profile.losses+case when recorded.outcome='loss' then 1 else 0 end,
    draws=profile.draws+case when recorded.outcome='draw' then 1 else 0 end,
    score=profile.score+recorded.score,
    updated_at=now()
  from recorded where profile.id=recorded.user_id;
end;
$$;
revoke all on function public.record_match(uuid,text,text,uuid,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.record_match(uuid,text,text,uuid,jsonb,jsonb) to service_role;

-- Source: Supabase/migrations/20261107_member_accounts.sql
-- Apply after 20261106_team_elo.sql. Authentication remains in Supabase auth.users;
-- profiles already holds the member's nickname and server-awarded statistics.

create or replace function public.touch_profile_updated_at()
returns trigger language plpgsql set search_path = public as $$
begin
  new.updated_at = now();
  return new;
end;
$$;
drop trigger if exists profile_updated_at on public.profiles;
create trigger profile_updated_at before update of nickname on public.profiles
  for each row execute function public.touch_profile_updated_at();
revoke all on function public.touch_profile_updated_at() from public, anon, authenticated;

-- Metadata only. A future verified payment-provider webhook may populate this
-- table using the server role. There is no checkout or client payment write API.
create table if not exists public.payment_records (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  description text not null check (char_length(description) between 1 and 160),
  amount_minor bigint not null check (amount_minor between 0 and 9007199254740991),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  status text not null check (status in ('pending','paid','failed','cancelled','refunded')),
  provider text check (provider is null or char_length(provider) between 1 and 64),
  provider_payment_id text check (provider_payment_id is null or char_length(provider_payment_id) between 1 and 200),
  created_at timestamptz not null default now(),
  unique (provider, provider_payment_id)
);
create index if not exists payment_records_user_history_idx on public.payment_records (user_id, created_at desc, id desc);
create index if not exists match_participants_user_idx on public.match_participants (user_id, match_id);

alter table public.payment_records enable row level security;
drop policy if exists "member payment history" on public.payment_records;
create policy "member payment history" on public.payment_records
  for select to authenticated using (auth.uid() = user_id and not coalesce((auth.jwt()->>'is_anonymous')::boolean,false));
revoke all on public.payment_records from public, anon, authenticated;
grant select (id,user_id,description,amount_minor,currency,status,created_at) on public.payment_records to authenticated;
grant all on public.payment_records to service_role;

-- Personal history remains private even when read directly through Supabase REST.
-- The public leaderboard continues to read the public profile statistics.
drop policy if exists "match participant read" on public.match_participants;
drop policy if exists "member participation history" on public.match_participants;
create policy "member participation history" on public.match_participants
  for select to authenticated using (auth.uid() = user_id and not coalesce((auth.jwt()->>'is_anonymous')::boolean,false));
drop policy if exists "match read" on public.matches;
drop policy if exists "member match history" on public.matches;
create policy "member match history" on public.matches
  for select to authenticated using (
    not coalesce((auth.jwt()->>'is_anonymous')::boolean,false)
    and exists (select 1 from public.match_participants p where p.match_id = matches.id and p.user_id = auth.uid())
  );
revoke all on public.matches, public.match_participants from public, anon, authenticated;
grant select on public.matches, public.match_participants to authenticated;
grant all on public.matches, public.match_participants to service_role;

notify pgrst, 'reload schema';
commit;

select 'Database setup complete' as status;
